-- =============================================================================
-- La tabla del CRUD de /productos.
--
-- Escrita en SQL estandar a proposito, no en el dialecto de PostgreSQL:
--
--   BIGINT GENERATED BY DEFAULT AS IDENTITY   en vez de   BIGSERIAL
--   TIMESTAMP WITH TIME ZONE                  en vez de   TIMESTAMPTZ
--
-- Las dos formas hacen lo mismo en PostgreSQL, pero solo las primeras las
-- entiende tambien H2, que es la base sobre la que corren las pruebas. Asi esta
-- misma migracion se ejecuta en las dos, y las pruebas verifican la migracion
-- de verdad en vez de saltarsela con un esquema inventado por Hibernate.
-- =============================================================================

CREATE TABLE producto (
    id        BIGINT                   GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre    VARCHAR(120)             NOT NULL,

    -- En pesos, entero. Ver la nota sobre punto flotante en Producto.java.
    precio    INTEGER                  NOT NULL,
    stock     INTEGER                  NOT NULL,
    creado_en TIMESTAMP WITH TIME ZONE NOT NULL,

    -- La misma regla que @PositiveOrZero en ProductoNuevo, repetida aqui a
    -- proposito. La validacion de Bean Validation protege a quien entra por la
    -- API; esta protege la tabla de todo lo demas: una migracion mal escrita,
    -- una carga masiva, alguien conectado con psql. Son dos puertas distintas y
    -- las dos tienen que estar cerradas.
    CONSTRAINT precio_no_negativo CHECK (precio >= 0),
    CONSTRAINT stock_no_negativo  CHECK (stock  >= 0)
);
